INSERT INTO _migration_437_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_homeostasis_s1_001', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which hormone lowers the concentration of glucose in the blood?', 'multiple_choice', NULL, '["A. Insulin","B. Glucagon","C. Adrenaline","D. Antidiuretic hormone (ADH)"]', 'A', 'Insulin, secreted by the beta cells of the islets of Langerhans in the pancreas, increases glucose uptake by cells and the conversion of glucose to glycogen in the liver, lowering blood glucose. Glucagon and adrenaline raise blood glucose, and ADH regulates water reabsorption in the kidney. Therefore the correct answer is A: Insulin.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_homeostasis_s1_002', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What is the term for the maintenance of a constant internal environment in the body?', 'multiple_choice', NULL, '["A. Osmoregulation","B. Homeostasis","C. Excretion","D. Thermoregulation"]', 'B', 'Homeostasis is the general term for keeping internal conditions such as blood glucose concentration, core temperature and water potential within narrow limits. Osmoregulation and thermoregulation are specific examples of homeostasis, while excretion is the removal of metabolic waste. Therefore the correct answer is B: Homeostasis.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_homeostasis_s1_003', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A rise in blood glucose concentration after a meal is detected by the pancreas. Which events follow?', 'multiple_choice', NULL, '["A. Alpha cells secrete glucagon, stimulating glycogen breakdown","B. The liver converts glycogen back into glucose","C. Beta cells secrete insulin, increasing glucose uptake and glycogen synthesis","D. ADH release increases water reabsorption in the kidney"]', 'C', 'High blood glucose stimulates the beta cells of the islets of Langerhans to release insulin. Insulin increases cellular uptake of glucose and promotes its conversion to glycogen and fat in the liver, returning blood glucose towards the set point — an example of negative feedback. Therefore the correct answer is C: Beta cells secrete insulin, increasing glucose uptake and glycogen synthesis.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_homeostasis_s1_004', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In which region of the nephron is essentially all filtered glucose normally reabsorbed into the blood?', 'multiple_choice', NULL, '["A. Loop of Henle","B. Distal convoluted tubule","C. Collecting duct","D. Proximal convoluted tubule"]', 'D', 'Glucose is small enough to pass into the filtrate at the glomerulus, but all of it is reabsorbed by co-transport with sodium ions and active transport in the proximal convoluted tubule, so the urine of a healthy person contains no glucose. Therefore the correct answer is D: Proximal convoluted tubule.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_homeostasis_s1_005', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'How does antidiuretic hormone (ADH) increase water reabsorption from the collecting duct?', 'multiple_choice', NULL, '["A. It causes vesicles containing aquaporins to fuse with the cell surface membranes of collecting duct cells","B. It makes the loop of Henle shorter","C. It increases the rate of glomerular filtration","D. It blocks sodium reabsorption in the proximal tubule"]', 'A', 'ADH binds to receptors on collecting duct cells, triggering vesicles carrying aquaporin water channels to fuse with their cell surface membranes. This raises the permeability of the duct to water, so more water leaves by osmosis into the concentrated tissue fluid of the medulla. Therefore the correct answer is A: It causes vesicles containing aquaporins to fuse with the cell surface membranes of collecting duct cells.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_homeostasis_s1_006', 'topic_alevel_bio_homeostasis', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student investigates how the body regulates blood glucose concentration and core temperature.', 'structured', NULL, NULL, '(a) A change in an internal factor away from its set point is detected by receptors and triggers responses by effectors that reverse the change, returning the factor towards normal; the response is then switched off once the set point is restored. (b) Glucagon, secreted by the alpha cells of the islets of Langerhans, acts on liver cells to stimulate the breakdown of glycogen to glucose (glycogenolysis) and the formation of glucose from other compounds (gluconeogenesis), raising blood glucose concentration. (c) Constriction of the arterioles diverts blood away from the surface capillaries of the skin, so less warm blood flows close to the body surface; less heat is therefore transferred to the surroundings by radiation, conserving core temperature.', '(a) A change in an internal factor away from its set point is detected by receptors and triggers responses by effectors that reverse the change, returning the factor towards normal; the response is then switched off once the set point is restored. (b) Glucagon, secreted by the alpha cells of the islets of Langerhans, acts on liver cells to stimulate the breakdown of glycogen to glucose (glycogenolysis) and the formation of glucose from other compounds (gluconeogenesis), raising blood glucose concentration. (c) Constriction of the arterioles diverts blood away from the surface capillaries of the skin, so less warm blood flows close to the body surface; less heat is therefore transferred to the surroundings by radiation, conserving core temperature.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_437_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_homeostasis_s1_006_a', 'q_albio_homeostasis_s1_006', 'a', 'State what is meant by negative feedback in homeostasis.', '2', 'A change in an internal factor away from its set point is detected by receptors and triggers responses by effectors that reverse the change, returning the factor towards normal; the response is then switched off once the set point is restored.', '1'),
('sqp_q_albio_homeostasis_s1_006_b', 'q_albio_homeostasis_s1_006', 'b', 'Describe the role of glucagon when blood glucose concentration falls below the set point.', '2', 'Glucagon, secreted by the alpha cells of the islets of Langerhans, acts on liver cells to stimulate the breakdown of glycogen to glucose (glycogenolysis) and the formation of glucose from other compounds (gluconeogenesis), raising blood glucose concentration.', '2'),
('sqp_q_albio_homeostasis_s1_006_c', 'q_albio_homeostasis_s1_006', 'c', 'Explain how vasoconstriction of arterioles near the skin surface helps to reduce heat loss.', '2', 'Constriction of the arterioles diverts blood away from the surface capillaries of the skin, so less warm blood flows close to the body surface; less heat is therefore transferred to the surroundings by radiation, conserving core temperature.', '3');
INSERT INTO _migration_437_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_437_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_437_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_437_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_437_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_437_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_437_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_437_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_437_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_437_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_437_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_437_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
